-- v0.134 break decisions
create table if not exists public.attendance_break_decisions (id bigint generated by default as identity primary key,store_id bigint not null,employee_id bigint not null references public.employees(id) on delete cascade,in_event_id bigint not null references public.attendance_events(id) on delete cascade,break_provided boolean,compensate_30m boolean not null default false,updated_by text,updated_at timestamptz not null default now(),unique(in_event_id));
alter table public.attendance_break_decisions enable row level security;
create or replace function public.admin_attendance_break_decisions(p_store_id bigint,p_from timestamp without time zone,p_to timestamp without time zone) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if; return coalesce((select jsonb_agg(to_jsonb(x)) from (select b.* from public.attendance_break_decisions b join public.attendance_events e on e.id=b.in_event_id where b.store_id=p_store_id and e.event_at>=p_from and e.event_at<p_to order by e.event_at) x),'[]'::jsonb); end$$;
create or replace function public.admin_attendance_break_decision_save(p_store_id bigint,p_employee_id bigint,p_in_event_id bigint,p_break_provided boolean,p_compensate_30m boolean) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_email text; begin if not public.can_manage_store(p_store_id) then raise exception 'NOT_AUTHORIZED'; end if; if not exists(select 1 from public.employees e where e.id=p_employee_id and e.store_id=p_store_id) then raise exception 'EMPLOYEE_STORE_MISMATCH'; end if; if not exists(select 1 from public.attendance_events a where a.id=p_in_event_id and a.employee_id=p_employee_id and a.event_type='IN') then raise exception 'IN_EVENT_NOT_FOUND'; end if; v_email:=coalesce(auth.jwt()->>'email','admin'); insert into public.attendance_break_decisions(store_id,employee_id,in_event_id,break_provided,compensate_30m,updated_by,updated_at) values(p_store_id,p_employee_id,p_in_event_id,p_break_provided,case when p_break_provided=false then p_compensate_30m else false end,v_email,now()) on conflict(in_event_id) do update set break_provided=excluded.break_provided,compensate_30m=excluded.compensate_30m,updated_by=excluded.updated_by,updated_at=now(); return jsonb_build_object('ok',true); end$$;
revoke all on function public.admin_attendance_break_decisions(bigint,timestamp without time zone,timestamp without time zone) from public; revoke all on function public.admin_attendance_break_decision_save(bigint,bigint,bigint,boolean,boolean) from public; grant execute on function public.admin_attendance_break_decisions(bigint,timestamp without time zone,timestamp without time zone) to authenticated; grant execute on function public.admin_attendance_break_decision_save(bigint,bigint,bigint,boolean,boolean) to authenticated;